create temporary table pet_classified on commit drop as
select x.*, case when duplicate_in_file then 'duplicate_skipped' when existing_match then 'existing_matched'
 when shared_phone or shared_website or shared_address or existing_phone_conflict or dnc_match then 'review_required' else bucket end as final_bucket,
 concat_ws('; ',nullif(review_reason,''),case when shared_phone then 'Shared phone between different source business names' end,
 case when shared_website then 'Shared domain between different source businesses; verify ownership/location' end,
 case when shared_address then 'Shared street address between source businesses; verify identity' end,
 case when existing_phone_conflict then 'Phone already belongs to another CRM business; Admin review' end,
 case when dnc_match then 'Active DNC suppression' end) as final_reason
from (select s.*,
 exists(select 1 from pet_source p where p.n<>s.n and p.name_key=s.name_key
   and ((p.phone_key<>'' and p.phone_key=s.phone_key) or (p.website is not null and regexp_replace(lower(p.website),'^https?://(www\.)?','','g')=regexp_replace(lower(s.website),'^https?://(www\.)?','','g')))
   and ((p.phone is not null and s.phone is null) or ((p.phone is null)=(s.phone is null) and ((p.website is not null and s.website is null) or ((p.website is null)=(s.website is null) and p.n<s.n))))) as duplicate_in_file,
 s.address ~ '^[0-9]' and exists(select 1 from pet_source p where regexp_replace(regexp_replace(lower(p.address),'[, ]*canada$',''),'[^a-z0-9]','','g')=regexp_replace(regexp_replace(lower(s.address),'[, ]*canada$',''),'[^a-z0-9]','','g') and p.name_key<>s.name_key) as shared_address,
 s.phone_key<>'' and exists(select 1 from pet_source p where p.phone_key=s.phone_key and p.name_key<>s.name_key) as shared_phone,
 s.website_key<>'' and exists(select 1 from pet_source p where p.website_key=s.website_key and p.name_key<>s.name_key) as shared_website,
 exists(select 1 from public.call_list_leads l join public.call_list_segments seg on seg.id=l.segment_id and seg.crm='lead_generation'
 where regexp_replace(lower(l.business_name),'[^a-z0-9]','','g')=s.name_key and
 ((s.phone_key<>'' and right(regexp_replace(coalesce(l.phone,''),'[^0-9]','','g'),10)=s.phone_key)
 or (s.phone_key='' and s.website_key<>'' and split_part(regexp_replace(lower(coalesce(l.website,'')),'^https?://(www\.)?','','g'),'/',1)=s.website_key)))
 or exists(select 1 from public.leadgen_leads l where regexp_replace(lower(l.business_name),'[^a-z0-9]','','g')=s.name_key and
 ((s.phone_key<>'' and right(regexp_replace(coalesce(l.phone,''),'[^0-9]','','g'),10)=s.phone_key)
 or (s.phone_key='' and s.website_key<>'' and split_part(regexp_replace(lower(coalesce(l.website,'')),'^https?://(www\.)?','','g'),'/',1)=s.website_key))) as existing_match,
 s.phone_key<>'' and (exists(select 1 from public.call_list_leads l join public.call_list_segments seg on seg.id=l.segment_id and seg.crm='lead_generation'
 where right(regexp_replace(coalesce(l.phone,''),'[^0-9]','','g'),10)=s.phone_key and regexp_replace(lower(l.business_name),'[^a-z0-9]','','g')<>s.name_key)
 or exists(select 1 from public.leadgen_leads l where right(regexp_replace(coalesce(l.phone,''),'[^0-9]','','g'),10)=s.phone_key and regexp_replace(lower(l.business_name),'[^a-z0-9]','','g')<>s.name_key)) as existing_phone_conflict,
 exists(select 1 from public.crm_dnc_suppressions d where d.status='active' and d.removed_at is null and d.block_phone and s.phone_key<>'' and right(d.normalized_phone,10)=s.phone_key) as dnc_match
 from pet_source s) x;


-- Data-only import; no schema, RLS, permission or pre-existing record changes.
create temporary table pet_baseline(table_name text,id uuid,digest text) on commit drop;
do $$ declare t text; begin
 foreach t in array array['call_list_leads','call_list_segments','leadgen_campaigns','leadgen_clients','leadgen_leads','leadgen_call_logs','leadgen_appointments','leadgen_emails','leadgen_conversions','leadgen_users','crm_dnc_suppressions'] loop
  execute format('insert into pet_baseline select %L,id,md5(to_jsonb(r)::text) from public.%I r',t,t);
 end loop;
end $$;
do $pet$
declare v_client uuid; v_campaign uuid; v_henry uuid; v_admin uuid; v_no uuid; v_web uuid; v_review uuid; t text; changed boolean;
begin
 perform pg_advisory_xact_lock(hashtextextended('leadgen-pet-niagara-125327',0));
 if exists(select 1 from public.call_list_segments where source_file_name='campaign-125327-search-924903-pet-sitter_niagara-falls-on-canada_a6456634bb089459defda8e251c9e820.csv') then
  raise exception 'Source already imported; inspect existing segments instead of restarting';
 end if;
 select id into strict v_client from public.leadgen_clients where name='Teknokraft Canada Inc.' and active;
 select id into strict v_henry from public.leadgen_users where full_name='Henry Osuji' and role='agent' and active;
 select id into strict v_admin from public.leadgen_users where role='admin' and active and id='2101e587-c4fd-40af-914a-46db900ac711';
 if exists(select 1 from public.leadgen_campaigns where client_id=v_client and name='Teknokraft Canada Inc. — Niagara Falls Pet Care') then
  raise exception 'Niagara Falls Pet Care campaign already exists; inspect before import';
 end if;
 insert into public.leadgen_campaigns(client_id,name,description,status,territory,target_industry,assigned_team,start_date,created_by,qualification_criteria)
 values(v_client,'Teknokraft Canada Inc. — Niagara Falls Pet Care',
  'Niagara Falls pet sitter / pet care website design and SEO prospecting for Henry Osuji. Website Review means agent qualification is required; no website defect is presumed. Exclude Brampton and Mississauga.',
  'active','Niagara Falls, Ontario','Pet Sitter / Pet Care','Henry Osuji','2026-10-01',v_admin,
  array['Confirm Niagara Falls service area and pet care business fit','Speak with decision maker','Qualify interest in website design, redesign or SEO without presuming a website defect']) returning id into v_campaign;
 insert into public.leadgen_campaign_agents(campaign_id,agent_id,assigned_by) values(v_campaign,v_henry,v_admin);
 insert into public.call_list_segments(crm,name,leadgen_campaign_id,status,created_by,campaign_name,industry,territory,source_file_name,source_file_type,total_uploaded_rows,deployed_at,deployed_by)
 values('lead_generation','Pet Sitter — Niagara Falls, Ontario — No Website — Henry Osuji',v_campaign,'active',v_admin,'Teknokraft Canada Inc. — Niagara Falls Pet Care','Pet Sitter / Pet Care','Niagara Falls, Ontario','campaign-125327-search-924903-pet-sitter_niagara-falls-on-canada_a6456634bb089459defda8e251c9e820.csv','csv',0,now(),v_admin) returning id into v_no;
 insert into public.call_list_segments(crm,name,leadgen_campaign_id,status,created_by,campaign_name,industry,territory,source_file_name,source_file_type,total_uploaded_rows,deployed_at,deployed_by)
 values('lead_generation','Pet Sitter — Niagara Falls, Ontario — Website Review — Henry Osuji',v_campaign,'active',v_admin,'Teknokraft Canada Inc. — Niagara Falls Pet Care','Pet Sitter / Pet Care','Niagara Falls, Ontario','campaign-125327-search-924903-pet-sitter_niagara-falls-on-canada_a6456634bb089459defda8e251c9e820.csv','csv',0,now(),v_admin) returning id into v_web;
 insert into public.call_list_segments(crm,name,leadgen_campaign_id,status,created_by,campaign_name,industry,territory,source_file_name,source_file_type,total_uploaded_rows)
 values('lead_generation','Pet Sitter — Niagara Falls, Ontario — Admin Review / Uncontactable',v_campaign,'draft',v_admin,'Teknokraft Canada Inc. — Niagara Falls Pet Care','Pet Sitter / Pet Care','Niagara Falls, Ontario','campaign-125327-search-924903-pet-sitter_niagara-falls-on-canada_a6456634bb089459defda8e251c9e820.csv','csv',0) returning id into v_review;
 insert into public.call_list_segment_agents(segment_id,agent_id) values(v_no,v_henry),(v_web,v_henry);
 insert into public.call_list_leads(segment_id,source_row_number,business_name,phone,email,website,street_address,city,province,postal_code,country,industry,notes,extra_fields,is_possible_duplicate,duplicate_reason,dnc_flag,assigned_agent_id,created_by)
 select case final_bucket when 'no_website' then v_no when 'website_review' then v_web else v_review end,
 n,name,phone,email,website,address,city,
 case when source->>'address' ~* '\mNY\M' then 'NY' when source->>'address' ~* ', ON' then 'ON' else null end,
 postal,case when source->>'address' ~* '\mNY\M' then 'United States' else 'Canada' end,'Pet Sitter / Pet Care',
 case final_bucket when 'no_website' then 'No identifiable business website in source; confirm website status during the call. A social/directory profile is not a standalone business website.'
 when 'website_review' then 'Website present; qualify website design, redesign, SEO, mobile experience or lead-generation needs without presuming a defect.' else final_reason end,
 jsonb_build_object('source_file','campaign-125327-search-924903-pet-sitter_niagara-falls-on-canada_a6456634bb089459defda8e251c9e820.csv','source_row',source,'website_category',final_bucket,'review_reason',final_reason),
 (shared_phone or shared_website or shared_address or existing_phone_conflict),case when shared_phone or shared_website or shared_address or existing_phone_conflict then final_reason end,dnc_match,
 case when final_bucket in ('no_website','website_review') then v_henry else null end,v_admin
 from pet_classified where final_bucket not in ('duplicate_skipped','existing_matched');
 update public.call_list_segments s set total_uploaded_rows=(select count(*) from public.call_list_leads l where l.segment_id=s.id) where s.id in(v_no,v_web,v_review);
 -- Compare every original row, including timestamps, notes and history.
 foreach t in array array['call_list_leads','call_list_segments','leadgen_campaigns','leadgen_clients','leadgen_leads','leadgen_call_logs','leadgen_appointments','leadgen_emails','leadgen_conversions','leadgen_users','crm_dnc_suppressions'] loop
  execute format('select exists(select 1 from pet_baseline b left join public.%I r on r.id=b.id where b.table_name=%L and (r.id is null or b.digest<>md5(to_jsonb(r)::text)))',t,t) into changed;
  if changed then raise exception 'Pre-existing rows changed in %; rollback',t; end if;
 end loop;
 if (select count(*) from public.call_list_leads where segment_id in(v_no,v_web))<>31 then raise exception 'Unexpected production count'; end if;
 if exists(select 1 from public.call_list_leads where segment_id in(v_no,v_web) and assigned_agent_id is distinct from v_henry) then raise exception 'Wrong production agent'; end if;
 if exists(select 1 from public.call_list_segment_agents where segment_id in(v_no,v_web) and agent_id<>v_henry) then raise exception 'Wrong segment agent'; end if;
 if exists(select 1 from public.call_list_segment_agents where segment_id=v_review) then raise exception 'Review segment must be Admin only'; end if;
end;
$pet$;
select jsonb_build_object('csv_rows',(select count(*) from pet_source),'classification',(select jsonb_object_agg(final_bucket,n) from(select final_bucket,count(*) n from pet_classified group by final_bucket)x),'flagged_records',(select count(*) from pet_classified where final_bucket='review_required' and(shared_phone or shared_website or shared_address or existing_phone_conflict)),'pre_existing_records_unchanged',true) as import_result;

commit;
